let vehicleReport=null,selectedVehicleId=null,selectedTrip=0;
let savedVehiclePlans=readStore('lg-vehicle-plans-v1',[]);
function addShipmentLine(line={}){if($('shipmentlines').children.length>=30){$('vehicleerror').textContent='Maximum 30 shipment lines.';return;}const row=document.createElement('div');row.className='shipmentline';row.innerHTML=`<label>LG model<input class="shipmodel" list="models" value="${esc(line.model||'')}" placeholder="Exact LG model"></label><label>Cartons<input class="shipquantity" type="number" min="1" max="100000" value="${line.quantity??24}"></label><label>Max layers<input class="shiplayers" type="number" min="1" max="100" value="${line.layers??1}"></label><label>Delivery stop<input class="shipstop" type="number" min="1" max="30" value="${line.stop??1}"></label><label>Destination<input class="shipdestination" maxlength="80" value="${esc(line.destination||'')}" placeholder="Customer / city"></label><label class="shipapproval"><input class="shipconfirmed" type="checkbox" ${line.stackConfirmed?'checked':''}> Stack limit verified</label><button class="textbtn shipremove" type="button" aria-label="Remove shipment line">✕</button>`;row.querySelector('.shipremove').onclick=()=>{row.remove();invalidateVehiclePlan()};row.querySelector('.shiplayers').oninput=()=>{row.querySelector('.shipconfirmed').checked=false;invalidateVehiclePlan()};row.addEventListener('input',invalidateVehiclePlan);$('shipmentlines').append(row);}
function readShipmentLines(){return [...$('shipmentlines').children].map(row=>({model:row.querySelector('.shipmodel').value.trim().toUpperCase(),quantity:Number(row.querySelector('.shipquantity').value),layers:Number(row.querySelector('.shiplayers').value),stackConfirmed:row.querySelector('.shipconfirmed').checked,stop:Number(row.querySelector('.shipstop').value),destination:row.querySelector('.shipdestination').value.trim()}));}
function vehicleProfiles(){return [...$('vehicleprofiles').children].filter(card=>card.querySelector('.vehicleenabled').checked).map(card=>{const p={id:card.dataset.vehicle,name:card.dataset.name};for(const field of ['L','W','H','payload','doorW','doorH','rate'])p[field]=Number(card.querySelector(`[data-field="${field}"]`).value);return p;});}
function vehiclePalletSettings(pallet=$('vehiclepallet').value){return {...settings(),L:1200,D:pallet==='euro'?800:1000,type:pallet,cartonsPerLayer:0};}
function vehicleOptions(){return {mode:$('vehiclemode').value,criterion:$('vehiclecriterion').value,gap:Number($('vehiclegap').value),stopMode:$('vehiclestopmode').value};}
function invalidateVehiclePlan(){vehicleReport=null;$('vehiclecomparison').replaceChildren();$('vehicleloadresults').replaceChildren();$('vehicleerror').textContent='';}
function setVehicleShipment(lines,pallet='standard',mode='pallets'){$('shipmentlines').replaceChildren();lines.forEach(addShipmentLine);$('vehiclepallet').value=pallet;$('vehiclemode').value=mode;$('vehiclepallet').disabled=mode==='cartons';invalidateVehiclePlan();}
function compareVehicleShipment(){try{if(!products.length)throw Error('The catalogue is loading. Please try again.');const lines=readShipmentLines(),profiles=vehicleProfiles();vehicleReport=$('vehiclemode').value==='custom'?manualVehicleReport(profiles):VehiclePlanner.compare(lines,products,profiles,vehiclePalletSettings(),vehicleOptions());selectedVehicleId=vehicleReport.recommended||vehicleReport.results[0]?.id;selectedTrip=0;renderVehicleComparison();}catch(error){$('vehicleerror').textContent=error.message;}}
function renderVehicleComparison(){const r=vehicleReport;if(!r)return;$('vehicleerror').textContent='';const recommended=r.results.find(p=>p.id===r.recommended);$('vehiclecomparison').innerHTML=`<div class="pageheading vehicleheading"><div><div class="eyebrow">VEHICLE COMPARISON</div><h2>${recommended?esc(recommended.name)+' recommended':'No configured vehicle can carry this load'}</h2><p>${esc(r.criterion)}.${recommended?` ${recommended.plan.totalCartons} cartons need ${recommended.plan.tripCount} load(s) in this profile.`:''} Based on the entered vehicle profiles; global packing optimality is not guaranteed.</p></div></div><div class="card tablewrap"><table><thead><tr><th>VEHICLE PROFILE</th><th>LOADS / TRIPS</th><th>FLOOR POSITIONS</th><th>AVG FLOOR USE</th><th>AVG PAYLOAD USE</th><th>EST. COST</th><th></th></tr></thead><tbody>${r.results.map(row=>row.ok?`<tr><td><strong>${esc(row.name)}</strong>${row.id===r.recommended?' <span class="status">Recommended</span>':''}</td><td>${row.plan.tripCount}</td><td>${row.plan.floorPositions}</td><td>${row.plan.averageFloorPercent}%</td><td>${(100*row.plan.totalWeight/(row.plan.tripCount*row.plan.vehicle.payload)).toFixed(1)}%</td><td>${row.plan.estimatedCost==null?'Rate not entered':row.plan.estimatedCost.toLocaleString()+' SAR'}</td><td><button class="textbtn" data-vehicleview="${esc(row.id)}">View loads</button></td></tr>`:`<tr><td><strong>${esc(row.name)}</strong></td><td colspan="6">${esc(row.error)}</td></tr>`).join('')}</tbody></table></div>`;document.querySelectorAll('[data-vehicleview]').forEach(b=>b.onclick=()=>{selectedVehicleId=b.dataset.vehicleview;selectedTrip=0;renderVehicleTrip()});renderVehicleTrip();}
function renderVehicleTrip(){const row=vehicleReport?.results.find(r=>r.id===selectedVehicleId&&r.ok);if(!row){$('vehicleloadresults').replaceChildren();return;}const plan=row.plan,v=plan.vehicle,t=plan.trips[selectedTrip]||plan.trips[0],colours=['#a7c297','#a4bdc7','#d7bd8e','#baa9c9','#9bbcb1'];const models=[...new Set(plan.lines.map(l=>l.model))];$('vehicleloadresults').innerHTML=`<div class="card vehicletrip"><div class="previewhead"><div><div class="eyebrow">${esc(v.name)} · ${plan.mode==='custom'?'YOUR 3D PALLETS':plan.mode==='pallets'?'PALLETIZED LOAD':'LOOSE CARTON STACKS'}</div><h2>Load ${t.number} of ${plan.tripCount}</h2></div><select id="vehicletripselect" aria-label="Select trip">${plan.trips.map((trip,i)=>`<option value="${i}" ${i===selectedTrip?'selected':''}>Load ${trip.number}</option>`).join('')}</select></div><div class="stats"><div class="stat"><strong>${t.weight.toLocaleString()} kg</strong><span>${t.payloadPercent}% of ${v.payload.toLocaleString()} kg usable payload</span></div><div class="stat"><strong>${t.floorPercent}%</strong><span>Body floor covered</span></div><div class="stat"><strong>${t.maxHeight} mm</strong><span>Maximum loaded height</span></div></div>${renderDispatchReport(t,v,plan.options)}<div class="truck3d"><div class="scenecontrols"><b>3D vehicle load · actual cargo height</b><label>Delivery stage<select id="truckstage"><option value="0">Before deliveries · full load</option>${[...new Set(t.placements.map(p=>p.stop??1))].sort((a,b)=>a-b).map(stop=>`<option value="${stop}">After stop ${stop}</option>`).join('')}</select></label><label>Rotate camera<input id="truckcamera" type="range" min="-170" max="170" value="35"></label></div><label class="custom"><input id="truckxray" type="checkbox"> Transparent view · see every carton edge</label><p id="truckstageinfo" class="muted" aria-live="polite"></p><svg id="truckcanvas" class="truckcanvas" role="img" aria-label="3D truck with cargo"></svg><p class="muted">Open body view. Dashed frame shows available cargo space. Numbers match the loading manifest. Each carton is drawn individually. Carton labels use floor-position.carton number. Older saved loads may show stack envelopes; recalculate them for individual cartons.</p></div><details><summary>2D floor plan</summary><div class="truckdrawing"><svg role="img" aria-label="Vehicle load floor plan with ${t.placements.length} non-overlapping floor positions" viewBox="-150 -180 ${v.L+300} ${v.W+440}"><rect x="0" y="0" width="${v.L}" height="${v.W}" fill="#f2f5ed" stroke="#517258" stroke-width="20"/><text x="30" y="-60" font-size="${Math.min(90,v.L/45)}" fill="#62785e">FRONT / CAB</text><text x="${v.L}" y="${v.W+150}" text-anchor="end" font-size="${Math.min(90,v.L/45)}" fill="#62785e">REAR / LOADING END</text>${t.placements.map(p=>`<rect x="${p.x}" y="${p.y}" width="${p.w}" height="${p.d}" fill="${colours[models.indexOf(p.model)%colours.length]}" stroke="#fff" stroke-width="8"/><text x="${p.x+p.w/2}" y="${p.y+p.d/2}" text-anchor="middle" dominant-baseline="middle" font-size="${Math.min(90,p.w/5,p.d/4)}" fill="#244b36">${p.loadOrder}</text>`).join('')}</svg></div></details><p class="muted">Internal body: ${v.L} × ${v.W} × ${v.H} mm · Door: ${v.doorW} × ${v.doorH} mm · Clearance between floor positions: ${plan.options.gap} mm. Vehicle boundaries include actual loaded pallet footprints and carton overhang.</p><div class="tablewrap"><table><thead><tr><th>LOAD / UNLOAD</th><th>STOP / DESTINATION</th><th>MODEL</th><th>TYPE</th><th>CARTONS</th><th>LAYERS</th><th>LOADED L × W × H MM</th><th>GROSS KG</th></tr></thead><tbody>${t.placements.map(p=>`<tr><td>${p.loadOrder} / ${p.unloadOrder??'—'}</td><td>${p.stop??1} · ${esc(p.destination||'')}</td><td>${esc(p.contents?Object.entries(p.contents).map(([m,q])=>m+' × '+q).join(', '):p.model)}</td><td>${esc(p.kind)}</td><td>${p.quantity}</td><td>${p.layers}</td><td>${p.w} × ${p.d} × ${p.H}</td><td>${p.weight}</td></tr>`).join('')}</tbody></table></div><p class="muted">Shipment total: ${plan.totalCartons} cartons · ${plan.totalWeight.toLocaleString()} kg across ${plan.tripCount} load(s). Load numbers run front to rear. Unload numbers follow delivery stops, then the rear-most position. Review access conflicts and remaining-load balance in the dispatch report. ${esc(plan.method)}</p><div class="actions"><button id="savevehicleplan" class="secondary">Save vehicle plan</button><button id="exportvehicleplan" class="secondary">Export manifest JSON</button><button id="exportdispatchcsv" class="secondary">Export dispatch CSV</button><button id="printvehicleplan" class="secondary">Print selected load / PDF</button></div></div>`;renderTruck3D(t,v);$('exportdispatchcsv').onclick=()=>exportDispatchCSV(plan);$('truckcamera').oninput=()=>renderTruck3D(t,v);$('truckxray').onchange=()=>renderTruck3D(t,v);$('truckstage').onchange=()=>renderTruck3D(t,v);$('printvehicleplan').onclick=()=>{document.body.dataset.printView='vehicle';window.print();};$('vehicletripselect').onchange=()=>{selectedTrip=Number($('vehicletripselect').value);renderVehicleTrip()};$('exportvehicleplan').onclick=()=>download(v.id+'-load-manifest.json',plan);$('savevehicleplan').onclick=()=>{const record={id:crypto.randomUUID(),created:new Date().toISOString(),report:JSON.parse(JSON.stringify(vehicleReport))};const next=[record,...savedVehiclePlans].slice(0,30);if(persist('lg-vehicle-plans-v1',next)){savedVehiclePlans=next;$('savevehicleplan').textContent='Saved ✓';$('savevehicleplan').disabled=true;}};}
function restoreVehicleInputs(report){const input=report.inputs;if(!input)return;if(input.manual){restoreManualBatch(input.batch);$('vehiclemode').value='custom';}else setVehicleShipment(input.lines,input.palletSettings?.type||'standard',input.options?.mode||'pallets');if(input.palletSettings)applyLoadSettings(input.palletSettings);$('vehiclecriterion').value=input.options?.criterion||'trips';$('vehiclegap').value=input.options?.gap??20;$('vehiclestopmode').value=input.options?.stopMode||'compact';for(const card of $('vehicleprofiles').children){const profile=input.vehicles.find(p=>p.id===card.dataset.vehicle);card.querySelector('.vehicleenabled').checked=!!profile;if(profile)for(const field of ['L','W','H','payload','doorW','doorH','rate'])card.querySelector(`[data-field="${field}"]`).value=profile[field]??0;}}
function renderVehicleHistory(){const section=document.createElement('div');section.innerHTML='<div class="pageheading vehicleheading"><h2>Vehicle load plans</h2></div>'+(savedVehiclePlans.length?savedVehiclePlans.map((record,i)=>{const p=record.report.results.find(r=>r.id===record.report.recommended)?.plan;return `<div class="card savedcard"><div><h3>${p?esc(p.vehicle.name)+' · '+p.totalCartons+' cartons':'Vehicle comparison'}</h3><p>${esc(new Date(record.created).toLocaleString())}</p></div><div class="actions"><button class="secondary" data-openvehicle="${i}">View</button><button class="secondary" data-exportvehicle="${i}">Export</button><button class="textbtn" data-deletevehicle="${i}">Delete</button></div></div>`}).join(''):'<p class="muted">No vehicle load plans saved.</p>');$('savedlist').append(section);section.querySelectorAll('[data-openvehicle]').forEach(b=>b.onclick=()=>{const report=savedVehiclePlans[Number(b.dataset.openvehicle)].report;restoreVehicleInputs(report);vehicleReport=report;selectedVehicleId=vehicleReport.recommended;selectedTrip=0;renderVehicleComparison();tab('vehicles')});section.querySelectorAll('[data-exportvehicle]').forEach(b=>b.onclick=()=>download('vehicle-comparison.json',savedVehiclePlans[Number(b.dataset.exportvehicle)].report));section.querySelectorAll('[data-deletevehicle]').forEach(b=>b.onclick=()=>{const next=savedVehiclePlans.filter((_,i)=>i!==Number(b.dataset.deletevehicle));if(persist('lg-vehicle-plans-v1',next)){savedVehiclePlans=next;renderSaved();renderVehicleHistory()}});}
$('vehicleprofiles').innerHTML=VehiclePlanner.templates.map(p=>`<details open class="vehicleprofile" data-vehicle="${p.id}" data-name="${esc(p.name)}"><summary>${esc(p.name)} · ${p.L} × ${p.W} × ${p.H} mm</summary><label class="custom"><input class="vehicleenabled" type="checkbox" checked> Include this profile</label><div class="fields two">${[['L','Internal length (mm)'],['W','Internal width (mm)'],['H','Allowed cargo height (mm)'],['payload','Usable payload (kg)'],['doorW','Door width (mm)'],['doorH','Door height (mm)'],['rate','Optional trip rate (SAR)']].map(([key,label])=>`<label>${label}<input data-field="${key}" type="number" min="${key==='rate'?0:1}" step="any" value="${p[key]}"></label>`).join('')}</div></details>`).join('');$('vehicleprofiles').addEventListener('input',invalidateVehiclePlan);for(const id of ['vehiclemode','vehiclepallet','vehiclecriterion','vehiclegap','vehiclestopmode'])$(id).addEventListener('change',invalidateVehiclePlan);$('addshipmentline').onclick=()=>{addShipmentLine();invalidateVehiclePlan()};$('comparevehicles').onclick=compareVehicleShipment;$('vehiclepalletsettings').onclick=()=>tab('planner');addShipmentLine();

window.addEventListener('afterprint',()=>{delete document.body.dataset.printView;});
$('vehiclemode').addEventListener('change',()=>{$('vehiclepallet').disabled=$('vehiclemode').value==='cartons';});

function renderTruck3D(trip,vehicle){const stage=Number($('truckstage').value)||0,shown={...trip,placements:trip.placements.filter(p=>(p.stop??1)>stage)};$('truckstageinfo').textContent=(stage?'After stop '+stage:'Before deliveries')+' · '+shown.placements.reduce((n,p)=>n+p.quantity,0)+' cartons · '+shown.placements.reduce((n,p)=>n+p.weight,0).toFixed(1)+' kg remaining. The report and 2D floor plan below describe the original full load.';const boxes=[{x:0,y:0,z:-80,w:vehicle.L,d:vehicle.W,h:80,background:-2,color:'#929e8a',title:'Truck floor'},...LoadScene3D.truckBoxes(shown)],drawing=LoadScene3D.scene(boxes,{angle:Number($('truckcamera').value),xray:$('truckxray').checked,wire:{x:0,y:0,z:0,w:vehicle.L,d:vehicle.W,h:vehicle.H}});$('truckcanvas').setAttribute('viewBox',drawing.viewBox);$('truckcanvas').innerHTML=drawing.html;}

function renderDispatchReport(trip,vehicle,options={}){
 const r=DispatchPlanner.analyse(trip,vehicle,options),b=r.balance;
 return `<div class="dispatchreport"><div class="previewhead"><h3>Dispatch & capacity report</h3><span class="badge">${options.stopMode==='rear-access'?'REAR-ACCESS ZONES':'COMPACT LOAD'}</span></div><div class="stats"><div class="stat"><strong>${r.payloadRemaining.toLocaleString()} kg</strong><span>Payload remaining</span></div><div class="stat"><strong>${+(r.heightClearance/10).toFixed(1)} cm</strong><span>Body / door height margin</span></div><div class="stat"><strong>${r.goodsCube} m³</strong><span>Carton volume · ${r.cubePercent}% of body cube</span></div></div><p>Estimated cargo centre from front / left / floor: <b>${b.centre.x===null?'Empty':[(b.centre.x/10).toFixed(1),(b.centre.y/10).toFixed(1),(b.centre.z/10).toFixed(1)].join(' / ')+' cm'}</b></p><div class="balancebars"><div><b>Front half ${b.frontKg} kg</b><div class="balancetrack"><i style="width:${b.frontPercent}%"></i></div><span>Rear half ${b.rearKg} kg</span></div><div><b>Left half ${b.leftKg} kg</b><div class="balancetrack"><i style="width:${b.leftPercent}%"></i></div><span>Right half ${b.rightKg} kg</span></div></div><h3>Delivery sequence & remaining load</h3><div class="tablewrap"><table><thead><tr><th>STOP / DESTINATION</th><th>DELIVER CARTONS</th><th>FLOOR POSITIONS</th><th>REMAINING KG</th><th>REMAINING FRONT / REAR KG</th><th>REMAINING LEFT / RIGHT KG</th><th>BALANCE REVIEW</th></tr></thead><tbody>${r.stages.map(s=>`<tr><td>${s.stop} · ${esc(s.destinations.join(', '))}</td><td>${s.cartons}</td><td>${s.positions}</td><td>${s.remaining.weight}</td><td>${s.remaining.frontKg} / ${s.remaining.rearKg}</td><td>${s.remaining.leftKg} / ${s.remaining.rightKg}</td><td>${!s.remaining.weight?'Empty':s.review?'Review concentration':'No threshold flagged'}</td></tr>`).join('')}</tbody></table></div>${r.notes.length?`<ul>${r.notes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul>`:'<p>No imbalance or straight rear-exit conflict flagged by these checks.</p>'}<p class="muted">${esc(r.method)}</p></div>`;
}
function exportDispatchCSV(plan){const blob=new Blob(['\uFEFF'+DispatchPlanner.csv(plan)],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=plan.vehicle.id+'-dispatch-manifest.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
